window.__votdWeek && window.__votdWeek({"week":"2028-10-23","reading":"Mormon 1–6","days":[{"d":"2028-10-23","ref":"Mormon 1:15","b":"Mormon","c":1,"v":15,"he":"וַאֲנִי בֶּן־חֲמֵשׁ עֶשְׂרֵה שָׁנָה וְדַעְתִּי מְיֻשֶּׁבֶת מְעַט וְעַל־כֵּן בָּא אֵלַי יְהוָה וָאֶטְעַם וָאֵדַע אֶת־חֶסֶד יֵשׁוּעַ׃","en":"And I, being fifteen years of age and being somewhat of a sober mind, therefore I was visited of the Lord, and tasted and knew of the goodness of Jesus."},{"d":"2028-10-24","ref":"Mormon 2:13","b":"Mormon","c":2,"v":13,"he":"אַךְ הִנֵּה שִׂמְחָתִי הָיְתָה לַשָּׁוְא כִּי יְגוֹנָם לֹא־הָיָה לָשׁוּב מִפְּנֵי חֶסֶד הָאֱלֹהִים כִּי־אִם הָיָה יְגוֹן הַנִּדּוֹנִים כִּי־לֹא יִתֵּן יְהוָה לָהֶם תָּמִיד לִמְצֹא שִׂמְחָה בַּחֵטְא׃","en":"But behold this my joy was vain, for their sorrowing was not unto repentance, because of the goodness of God; but it was rather the sorrowing of the damned, because the Lord would not always suffer them to take happiness in sin."},{"d":"2028-10-25","ref":"Mormon 3:15","b":"Mormon","c":3,"v":15,"he":"נְקָמָה לִי וַאֲנִי אֲשַׁלֵּם וְיַעַן לֹא־שָׁב הָעָם־הַזֶּה אַחֲרֵי הַצִּילִי אוֹתָם הִנֵּה יִכָּרְתוּ מֵעַל פְּנֵי הָאֲדָמָה׃","en":"Vengeance is mine, and I will repay; and because this people repented not after I had delivered them, behold, they shall be cut off from the face of the earth."},{"d":"2028-10-26","ref":"Mormon 3:18","b":"Mormon","c":3,"v":18,"he":"אַף הִנְנִי כֹּתֵב אֶל־כׇּל־קְצוֹת הָאָרֶץ אַף אֲלֵיכֶם שְׁנֵים עָשָׂר שִׁבְטֵי יִשְׂרָאֵל אֲשֶׁר תִּשָּׁפְטוּ כְּפִי מַעֲשֵׂיכֶם בִּידֵי הַשְּׁנֵים עָשָׂר אֲשֶׁר בָּחַר יֵשׁוּעַ לִהְיוֹת תַּלְמִידָיו בְּאֶרֶץ יְרוּשָׁלַיִם׃","en":"Yea, behold, I write unto all the ends of the earth; yea, unto you, twelve tribes of Israel, who shall be judged according to your works by the twelve whom Jesus chose to be his disciples in the land of Jerusalem."},{"d":"2028-10-27","ref":"Mormon 4:12","b":"Mormon","c":4,"v":12,"he":"וְלֹא־הָיָה רֶשַׁע גָּדוֹל כָּזֶה בְּכׇל־בְּנֵי לֶחִי וְאַף לֹא בְּכׇל־בֵּית יִשְׂרָאֵל כִּדְבַר יְהוָה כַּאֲשֶׁר הָיָה בָּעָם הַזֶּה׃","en":"And there never had been so great wickedness among all the children of Lehi, nor even among all the house of Israel, according to the words of the Lord, as was among this people."},{"d":"2028-10-28","ref":"Mormon 5:16","b":"Mormon","c":5,"v":16,"he":"כִּי הִנֵּה רוּחַ יְהוָה כְּבָר חָדַל לְהֵאָבֵק עִם־אֲבוֹתֵיהֶם וְהֵם בְּלִי מָשִׁיחַ וֵאלֹהִים בָּעוֹלָם וְנִדָּפִים הֵם כַּמּוֹץ לִפְנֵי הָרוּחַ׃","en":"For behold, the Spirit of the Lord hath already ceased to strive with their fathers; and they are without Christ and God in the world; and they are driven about as chaff before the wind."},{"d":"2028-10-29","ref":"Mormon 6:22","b":"Mormon","c":6,"v":22,"he":"מִי־יִתֵּן שַׁבְתֶּם טֶרֶם בָּא עֲלֵיכֶם הַשֶּׁבֶר הַגָּדוֹל הַזֶּה אַךְ הִנֵּה הֲלַכְתֶּם וְהָאָב אַף אֲבִי הַשָּׁמַיִם אֲשֶׁר־לְעוֹלָם יוֹדֵעַ דַּרְכְּכֶם וְהוּא יַעֲשֶׂה עִמָּכֶם כְּצִדְקָתוֹ וְחַסְדּוֹ׃","en":"O that ye had repented before this great destruction had come upon you. But behold, ye are gone, and the Father, yea, the Eternal Father of heaven, knoweth your state; and he doeth with you according to his justice and mercy."}]});
